def solve_sudoku(grid: str) -> str:
    """
    数独を解き、解の一意性を判定する。
    解が唯一の場合、盤面を文字列で返す。それ以外の場合、ValueErrorを送出する。
    """
    if len(grid) != 81:
        raise ValueError("入力グリッドの長さは81文字である必要があります。")

    # 1. 文字種と初期バリデーション
    for char in grid:
        if char not in '123456789.':
            raise ValueError("グリッドには '1'-'9' または '.' の文字のみを含める必要があります。")

    board = [list(grid[i:i+9]) for i in range(0, 81, 9)]

    def is_safe(r, c, num, current_board):
        # 行チェック
        for col in range(9):
            if current_board[r][col] == num and col != c:
                return False

        # 列チェック
        for row in range(9):
            if current_board[row][c] == num and row != r:
                return False

        # 3x3ブロックチェック
        start_row = (r // 3) * 3
        start_col = (c // 3) * 3
        for i in range(3):
            for j in range(3):
                curr_r = start_row + i
                curr_c = start_col + j
                if current_board[curr_r][curr_c] == num and (curr_r != r or curr_c != c):
                    return False
        return True

    # 初期矛盾チェック
    for r in range(9):
        for c in range(9):
            if board[r][c] != '.':
                num = board[r][c]
                # 仮にマスが空であるとして、その初期値が他のマスと衝突していないかチェックする
                if not is_safe(r, c, num, board):
                    raise ValueError("初期の配置に矛盾があります。")

    # ----------------------------------------------------------------------
    # バックトラッキングによる解の探索とカウント
    # ----------------------------------------------------------------------

    # 探索中に例外を発生させて強制終了する仕組みを使用する
    class UniqueSolutionFound(Exception):
        pass

    class MultipleSolutionsFound(Exception):
        pass

    # グローバルな状態を管理する変数（解の候補と結果の格納）
    solution_count = 0
    unique_solution_board = None

    def solve_recursive(current_board):
        nonlocal solution_count, unique_solution_board

        if solution_count >= 2:
            raise MultipleSolutionsFound()

        # 空きマスを探す (最優先で候補が少ないマスを選ぶMRV戦略的な探索)
        empty_cells = []
        for r in range(9):
            for c in range(9):
                if current_board[r][c] == '.':
                    empty_cells.append((r, c))

        if not empty_cells:
            # 全て埋まった -> 1つの解が見つかった
            if solution_count == 0:
                solution_count = 1
                # 結果を保持するために、盤面をコピーして保存する
                unique_solution_board = ["".join(row) for row in current_board]
            elif solution_count == 1:
                solution_count = 2
            return

        # MRV (Minimum Remaining Values) 戦略を擬似的に行う:
        # 候補数が最も少ないマスを次に試行する。
        best_cell = None
        min_candidates = 10

        # 各空きマスについて、現在の制約下での候補数を数える
        candidates_by_cell = {}
        for r, c in empty_cells:
            candidates = set()
            for num in "123456789":
                if num not in current_board[r] and num not in [current_board[i][c] for i in range(9)] and num not in get_block_values(r, c, current_board):
                    candidates.add(num)
            candidates_by_cell[(r, c)] = candidates

            if len(candidates) < min_candidates:
                min_candidates = len(candidates)
                best_cell = (r, c)

        if best_cell is None:
             # 予期せぬ状態（空きマスがあるのに候補が見つからない場合）
            if solution_count == 0:
                 # 矛盾がある可能性が高い。ただし、初期チェックを通過しているので、
                 # これは解が存在しないケース（バックトラックの限界）として扱う。
                 pass
            return


        r, c = best_cell

        # 候補を試す (MCV/LVCの恩恵を最大化するため、候補の昇順で試すことが多いが、ここでは単純に反復する)
        candidates = candidates_by_cell[(r, c)]
        sorted_candidates = sorted(list(candidates))

        # 盤面の状態を深さ優先で管理するため、コピーを作成する
        for num in sorted_candidates:
            # 試行
            current_board[r][c] = num

            solve_recursive(current_board)

            # 後退（Backtrack）
            current_board[r][c] = '.'

            if solution_count >= 2:
                # 既に2つ以上の解が見つかったため、即座に停止
                raise MultipleSolutionsFound()

    def get_block_values(r, c, board):
        start_row = (r // 3) * 3
        start_col = (c // 3) * 3
        values = set()
        for i in range(3):
            for j in range(3):
                values.add(board[start_row + i][start_col + j])
        return values

    # メインの実行ブロック
    try:
        solve_recursive(board)
    except MultipleSolutionsFound:
        # 解が2つ以上ある場合
        raise ValueError("解が複数存在します。")
    except Exception:
        # 例外がキャッチされず終了した場合（通常は到達しないはず）
        pass

    # 判定と返却
    if solution_count == 0:
        # 解が存在しない場合（矛盾は初期チェックで処理済みだが、解が埋められない場合）
        raise ValueError("解が存在しません。")
    elif solution_count == 1:
        # 解が唯一の場合
        return "".join(unique_solution_board)
    else: # solution_count == 2 の場合、MultipleSolutionsFoundで処理済み
        # ここには来ないが、念のため
        raise ValueError("解が複数存在します。")

